-- Nschess production Store catalog synchronization (207 frontend items)
-- Run this whole block in the Supabase SQL Editor.
-- It changes only public.store_catalog and its item_type CHECK constraint.

begin;

-- Validate the deployed Store schema and required function signatures before any write.
do $$
declare
  missing_columns text[];
  fn_missing text[];
  constraint_name text;
begin
  if to_regclass('public.store_catalog') is null then
    raise exception 'STORE_SCHEMA_MISSING: public.store_catalog does not exist; apply the Store authority migration first';
  end if;

  if not has_table_privilege(current_user, 'public.store_catalog', 'INSERT')
     or not has_table_privilege(current_user, 'public.store_catalog', 'UPDATE') then
    raise exception 'STORE_PERMISSION_DENIED: SQL Editor role cannot INSERT and UPDATE public.store_catalog';
  end if;

  select array_agg(required_name order by required_name)
    into missing_columns
  from (values
    ('item_id'), ('item_type'), ('name'), ('cost_coins'), ('rarity'),
    ('unlock_method'), ('giftable'), ('active'), ('metadata'), ('updated_at')
  ) as required(required_name)
  where not exists (
    select 1 from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name = 'store_catalog'
      and c.column_name = required.required_name
  );
  if missing_columns is not null then
    raise exception 'STORE_SCHEMA_MISMATCH: public.store_catalog is missing columns %', missing_columns;
  end if;

  select array_agg(required_name || '(' || required_args || ')' order by required_name)
    into fn_missing
  from (values
    ('admin_upsert_store_catalog', 'jsonb'),
    ('get_store_state', ''),
    ('purchase_cosmetic', 'text, text')
  ) as required(required_name, required_args)
  where not exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname = required.required_name
      and (
        (required.required_name = 'admin_upsert_store_catalog' and p.pronargs = 1 and p.proargtypes[0] = 'jsonb'::regtype::oid)
        or (required.required_name = 'get_store_state' and p.pronargs = 0)
        or (required.required_name = 'purchase_cosmetic' and p.pronargs = 2 and p.proargtypes[0] = 'text'::regtype::oid and p.proargtypes[1] = 'text'::regtype::oid)
      )
  );
  if fn_missing is not null then
    raise exception 'STORE_FUNCTION_SIGNATURE_MISMATCH: missing %', fn_missing;
  end if;

  -- The original constraint predates Arrow Skins. Replace only the catalog
  -- item_type check, preserving every other constraint and every row.
  if not exists (
       select 1 from pg_constraint c
       where c.conrelid = 'public.store_catalog'::regclass
         and c.contype = 'c'
         and pg_get_constraintdef(c.oid) ilike '%item_type%'
     ) or exists (
       select 1 from pg_constraint c
       where c.conrelid = 'public.store_catalog'::regclass
         and c.contype = 'c'
         and pg_get_constraintdef(c.oid) ilike '%item_type%'
         and pg_get_constraintdef(c.oid) not ilike '%arrowSkin%'
     ) then
    for constraint_name in
      select c.conname
      from pg_constraint c
      where c.conrelid = 'public.store_catalog'::regclass
        and c.contype = 'c'
        and pg_get_constraintdef(c.oid) ilike '%item_type%'
    loop
      execute format('alter table public.store_catalog drop constraint %I', constraint_name);
    end loop;
    alter table public.store_catalog add constraint store_catalog_item_type_check check (item_type in (
      'board', 'skin', 'pieceFinish', 'backgroundTheme', 'avatar', 'avatarEffect',
      'frame', 'nameStyle', 'lastMove', 'boardBorder', 'archetype', 'musicPack',
      'sfxPack', 'title', 'trail', 'flexBadge', 'arrowSkin'
    ));
  end if;
end
$$;

create temporary table expected_store_catalog (
