as rows(item_id text, item_type text, name text, cost_coins bigint, rarity text, unlock_method text, giftable boolean, active boolean, metadata jsonb);

-- Refuse to run if the pasted payload is not the complete generated export.
do $$
declare payload_count integer;
begin
  select count(*) into payload_count from expected_store_catalog;
  if payload_count <> 207 then
    raise exception 'STORE_PAYLOAD_INCOMPLETE: expected 207 frontend items, received %', payload_count;
  end if;
end
$$;

-- Upsert only catalog rows. No profile, wallet, inventory, ownership,
-- equipped-state, preference, transaction, or purchase-history table is touched.
insert into public.store_catalog(
  item_id, item_type, name, cost_coins, rarity, unlock_method,
  giftable, active, metadata, updated_at
)
select item_id, item_type, name, cost_coins, rarity, unlock_method,
       giftable, active, metadata, now()
from expected_store_catalog
on conflict (item_id) do update set
  item_type = excluded.item_type,
  name = excluded.name,
  cost_coins = excluded.cost_coins,
  rarity = excluded.rarity,
  unlock_method = excluded.unlock_method,
  giftable = excluded.giftable,
  active = excluded.active,
  metadata = excluded.metadata,
  updated_at = now();

-- Report the exact result, including inactive/missing IDs and stale extras.
with missing as (
  select e.item_id
  from expected_store_catalog e
  left join public.store_catalog s
    on s.item_id = e.item_id and s.active is true
  where s.item_id is null
), mismatches as (
  select e.item_id
  from expected_store_catalog e
  join public.store_catalog s on s.item_id = e.item_id and s.active is true
  where s.item_type is distinct from e.item_type
     or s.name is distinct from e.name
     or s.cost_coins is distinct from e.cost_coins
     or s.rarity is distinct from e.rarity
     or s.unlock_method is distinct from e.unlock_method
     or s.giftable is distinct from e.giftable
     or s.metadata is distinct from e.metadata
), extras as (
  select s.item_id
  from public.store_catalog s
  left join expected_store_catalog e on e.item_id = s.item_id
  where s.active is true and e.item_id is null
)
select jsonb_build_object(
  'expected_frontend_items', (select count(*) from expected_store_catalog),
  'server_active_items', (select count(*) from public.store_catalog where active is true),
  'missing_count', (select count(*) from missing),
  'missing_ids', coalesce((select jsonb_agg(item_id order by item_id) from missing), '[]'::jsonb),
  'mismatched_count', (select count(*) from mismatches),
  'mismatched_ids', coalesce((select jsonb_agg(item_id order by item_id) from mismatches), '[]'::jsonb),
  'extra_active_server_count', (select count(*) from extras),
  'extra_active_server_ids', coalesce((select jsonb_agg(item_id order by item_id) from extras), '[]'::jsonb)
) as store_catalog_verification;

-- Fail clearly and roll back if the active production catalog is still not
-- complete or any canonical frontend field differs.
do $$
declare
  missing_count integer;
  mismatch_count integer;
  missing_ids text;
begin
  select count(*) into missing_count
  from expected_store_catalog e
  left join public.store_catalog s on s.item_id = e.item_id and s.active is true
  where s.item_id is null;

  select count(*) into mismatch_count
  from expected_store_catalog e
  join public.store_catalog s on s.item_id = e.item_id and s.active is true
  where s.item_type is distinct from e.item_type
     or s.name is distinct from e.name
     or s.cost_coins is distinct from e.cost_coins
     or s.rarity is distinct from e.rarity
     or s.unlock_method is distinct from e.unlock_method
     or s.giftable is distinct from e.giftable
     or s.metadata is distinct from e.metadata;

  if missing_count > 0 or mismatch_count > 0 then
    select coalesce(string_agg(e.item_id, ', ' order by e.item_id), '(none)') into missing_ids
    from expected_store_catalog e
    left join public.store_catalog s on s.item_id = e.item_id and s.active is true
    where s.item_id is null;
    raise exception using
      errcode = 'P0001',
      message = format('STORE_CATALOG_INCOMPLETE: missing=%s mismatched=%s missing_ids=%s', missing_count, mismatch_count, missing_ids);
  end if;
end
$$;

commit;
